use std::collections::{
    BTreeMap,
    BTreeSet
};
use crate::tac_parser::{
    Function,
    Line
};
#[derive(Clone)]
pub struct Block {
    pub first: usize,
    pub last: usize,
    pub labels: Vec<String>,
    pub predecessors: Vec<usize>,
    pub successors: Vec<usize>
}
#[derive(Clone)]
pub struct Loop {
    pub header: usize,
    pub latches: BTreeSet<usize>,
    pub blocks: BTreeSet<usize>,
    pub exits: BTreeSet<usize>,
    pub outside: BTreeSet<usize>,
    pub depth: usize
}
pub struct Graph {
    pub blocks: Vec<Block>,
    pub owners: Vec<usize>,
    pub reachable: BTreeSet<usize>,
    pub postorder: Vec<usize>,
    pub order: Vec<usize>,
    pub dominators: Vec<BTreeSet<usize>>,
    pub idom: Vec<Option<usize>>,
    pub loops: Vec<Loop>,
    pub depths: Vec<usize>
}
fn visit(block: usize, blocks: &[Block], seen: &mut BTreeSet<usize>, order: &mut Vec<usize>) {
    if !seen.insert(block) {
        return;
    }
    for &next in &blocks[block].successors {
        visit(next, blocks, seen, order);
    }
    order.push(block);
}
pub fn build(function: &Function) -> Graph {
    let instructions = function.instructions();
    let mut labels: Vec<Vec<String>> = vec![Vec::new(); instructions.len()];
    let mut n = 0;
    for line in &function.code {
        match line {
            Line::Label(label) => labels[n].push(label.clone()),
            Line::Instruction(_) => n += 1
        }
    }
    let mut leaders = vec![0];
    for i in 1..instructions.len() {
        if !labels[i].is_empty() || ["goto", "if", "return"].contains(&instructions[i - 1].kind) {
            leaders.push(i);
        }
    }
    let mut blocks = Vec::new();
    let mut owners = vec![0; instructions.len()];
    let mut label_blocks = BTreeMap::new();
    for (b, &first) in leaders.iter().enumerate() {
        let last = if b + 1 < leaders.len() {
            leaders[b + 1] - 1
        } else {
            instructions.len() - 1
        };
        for i in first..=last {
            owners[i] = b;
        }
        for label in &labels[first] {
            label_blocks.insert(label.clone(), b);
        }
        blocks.push(Block {
            first,
            last,
            labels: labels[first].clone(),
            predecessors: Vec::new(),
            successors: Vec::new()
        });
    }
    for b in 0..blocks.len() {
        let last = &instructions[blocks[b].last];
        let mut successors = Vec::new();
        if last.kind != "goto" && last.kind != "return" {
            successors.push(b + 1);
        }
        if last.kind == "goto" || last.kind == "if" {
            let target = label_blocks[&last.target];
            if !successors.contains(&target) {
                successors.push(target);
            }
        }
        blocks[b].successors = successors;
    }
    for b in 0..blocks.len() {
        for next in blocks[b].successors.clone() {
            blocks[next].predecessors.push(b);
        }
    }
    let mut reachable = BTreeSet::new();
    let mut postorder = Vec::new();
    visit(0, &blocks, &mut reachable, &mut postorder);
    let order: Vec<usize> = postorder.iter().rev().copied().collect();
    let mut dominators = vec![BTreeSet::new(); blocks.len()];
    for &b in &reachable {
        dominators[b] = if b == 0 {
            BTreeSet::from([0])
        } else {
            reachable.clone()
        };
    }
    loop {
        let mut changed = false;
        for &b in order.iter().skip(1) {
            let mut intersection = reachable.clone();
            for &p in &blocks[b].predecessors {
                if reachable.contains(&p) {
                    intersection = intersection.intersection(&dominators[p]).copied().collect();
                }
            }
            intersection.insert(b);
            if intersection != dominators[b] {
                dominators[b] = intersection;
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }
    let mut idom = vec![None; blocks.len()];
    for &b in reachable.iter().filter(|&&b| b != 0) {
        idom[b] = dominators[b].iter().filter(|&&d| d != b).max_by_key(|&&d| dominators[d].len()).copied();
    }
    let mut headers: BTreeMap<usize,
    BTreeSet<usize>> = BTreeMap::new();
    for &tail in &reachable {
        for &head in &blocks[tail].successors {
            if dominators[tail].contains(&head) {
                headers.entry(head).or_default().insert(tail);
            }
        }
    }
    let mut loops = Vec::new();
    for (header, latches) in headers {
        let mut members = latches.clone();
        members.insert(header);
        let mut pending: Vec<usize> = latches.iter().copied().filter(|&b| b != header).collect();
        while let Some(b) = pending.pop() {
            for &p in &blocks[b].predecessors {
                if reachable.contains(&p) && members.insert(p) && p != header {
                    pending.push(p);
                }
            }
        }
        let mut exits = BTreeSet::new();
        let mut outside = BTreeSet::new();
        for &b in &members {
            if instructions[blocks[b].last].kind == "return" {
                exits.insert(b);
            }
            for &s in &blocks[b].successors {
                if !members.contains(&s) {
                    outside.insert(s);
                    exits.insert(b);
                }
            }
        }
        loops.push(Loop {
            header,
            latches,
            blocks: members,
            exits,
            outside,
            depth: 0
        });
    }
    for i in 0..loops.len() {
        loops[i].depth = loops.iter().filter(|l| l.blocks.contains(&loops[i].header)).count();
    }
    let depths = (0..blocks.len()).map(|b| loops.iter().filter(|l| l.blocks.contains(&b)).count()).collect();
    Graph {
        blocks,
        owners,
        reachable,
        postorder,
        order,
        dominators,
        idom,
        loops,
        depths
    }
}

use std::collections::BTreeSet;
use crate::tac_parser::{
    Instruction,
    Function,
    Expression,
    Operand
};
use crate::cfg::Graph;
pub type Definitions = BTreeSet<(String, usize)>;
pub type Copies = BTreeSet<(String, String)>;
pub struct Flow<T: Ord> {
    pub input: Vec<BTreeSet<T>>,
    pub output: Vec<BTreeSet<T>>,
    pub iterations: usize
}
pub struct Analysis {
    pub reaching: Flow<(String, usize)>,
    pub live: Flow<String>,
    pub available: Flow<Expression>,
    pub copies: Flow<(String, String)>,
    pub before_definitions: Vec<Definitions>,
    pub before_expressions: Vec<BTreeSet<Expression>>,
    pub before_copies: Vec<Copies>,
    pub live_before: Vec<BTreeSet<String>>,
    pub live_after: Vec<BTreeSet<String>>
}
pub fn reaching_transfer(set: &mut Definitions, instruction: &Instruction, number: usize) {
    if let Some(destination) = &instruction.destination {
        set.retain(|d| d.0 != *destination);
        set.insert((destination.clone(), number));
    }
}
pub fn live_transfer(set: &mut BTreeSet<String>, instruction: &Instruction) {
    if let Some(destination) = &instruction.destination {
        set.remove(destination);
    }
    set.extend(instruction.used());
}
fn expression_transfer(set: &mut BTreeSet<Expression>, instruction: &Instruction) {
    if let Some(expression) = instruction.expression() {
        set.insert(expression);
    }
    if instruction.kind == "store" {
        set.retain(|e| e.kind != "load" || e.operation != instruction.array);
    }
    if instruction.kind == "call" {
        set.retain(|e| e.kind != "load");
    }
    if let Some(destination) = &instruction.destination {
        set.retain(|e| !e.uses(destination));
    }
}
fn copy_transfer(set: &mut Copies, instruction: &Instruction) {
    if let Some(destination) = &instruction.destination {
        set.retain(|e| e.0 != *destination && e.1 != *destination);
        if instruction.kind == "copy" {
            if let Some(Operand::Variable(source)) = &instruction.a {
                if source != destination {
                    set.insert((destination.clone(), source.clone()));
                }
            }
        }
    }
}
fn forward<T: Ord + Clone, F: Fn(&mut BTreeSet<T>, &Instruction, usize)>(function: &Function, graph: &Graph, universe: BTreeSet<T>, parameter_definitions: Option<BTreeSet<T>>, transfer: F) -> Flow<T> {
    let instructions = function.instructions();
    let mut input = vec![BTreeSet::new(); graph.blocks.len()];
    let mut output = vec![universe.clone(); graph.blocks.len()];
    let mut iterations = 0;
    loop {
        iterations += 1;
        let mut changed = false;
        for &b in &graph.order {
            let mut set = if parameter_definitions.is_some() {
                BTreeSet::new()
            } else if b == 0 {
                BTreeSet::new()
            } else {
                universe.clone()
            };
            for &p in &graph.blocks[b].predecessors {
                if graph.reachable.contains(&p) {
                    if parameter_definitions.is_some() {
                        set.extend(output[p].iter().cloned());
                    } else if b != 0 {
                        set = set.intersection(&output[p]).cloned().collect();
                    }
                }
            }
            if b == 0 {
                if let Some(parameters) = &parameter_definitions {
                    set.extend(parameters.iter().cloned());
                }
            }
            input[b] = set.clone();
            for i in graph.blocks[b].first..=graph.blocks[b].last {
                transfer(&mut set, &instructions[i], i + 1);
            }
            if output[b] != set {
                output[b] = set;
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }
    Flow {
        input,
        output,
        iterations
    }
}
pub fn analyze(function: &Function, graph: &Graph) -> Analysis {
    let instructions = function.instructions();
    let mut universe = BTreeSet::new();
    let mut copies = Copies::new();
    for (i, instruction) in instructions.iter().enumerate() {
        if !graph.reachable.contains(&graph.owners[i]) {
            continue;
        }
        if let Some(expression) = instruction.expression() {
            universe.insert(expression);
        }
        if instruction.kind == "copy" {
            if let (Some(destination), Some(Operand::Variable(source))) = (&instruction.destination, &instruction.a) {
                if destination != source {
                    copies.insert((destination.clone(), source.clone()));
                }
            }
        }
    }
    let reaching = forward(function, graph, Definitions::new(), Some(function.parameters.iter().map(|p| (p.clone(), 0)).collect()), reaching_transfer);
    let available = forward(function, graph, universe, None, |s, i, _| expression_transfer(s, i));
    let copies = forward(function, graph, copies, None, |s, i, _| copy_transfer(s, i));
    let mut input = vec![BTreeSet::new(); graph.blocks.len()];
    let mut output = input.clone();
    let mut iterations = 0;
    loop {
        iterations += 1;
        let mut changed = false;
        for &b in &graph.postorder {
            let mut set = BTreeSet::new();
            for &s in &graph.blocks[b].successors {
                set.extend(input[s].iter().cloned());
            }
            output[b] = set.clone();
            for i in (graph.blocks[b].first..=graph.blocks[b].last).rev() {
                live_transfer(&mut set, &instructions[i]);
            }
            if set != input[b] {
                input[b] = set;
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }
    let live = Flow {
        input,
        output,
        iterations
    };
    let mut before_definitions = vec![Definitions::new(); instructions.len()];
    let mut before_expressions = vec![BTreeSet::new(); instructions.len()];
    let mut before_copies = vec![Copies::new(); instructions.len()];
    let mut live_before = vec![BTreeSet::new(); instructions.len()];
    let mut live_after = live_before.clone();
    for &b in &graph.reachable {
        let mut definitions = reaching.input[b].clone();
        let mut expressions = available.input[b].clone();
        let mut cs = copies.input[b].clone();
        for i in graph.blocks[b].first..=graph.blocks[b].last {
            before_definitions[i] = definitions.clone();
            before_expressions[i] = expressions.clone();
            before_copies[i] = cs.clone();
            reaching_transfer(&mut definitions, &instructions[i], i + 1);
            expression_transfer(&mut expressions, &instructions[i]);
            copy_transfer(&mut cs, &instructions[i]);
        }
        let mut lives = live.output[b].clone();
        for i in (graph.blocks[b].first..=graph.blocks[b].last).rev() {
            live_after[i] = lives.clone();
            live_transfer(&mut lives, &instructions[i]);
            live_before[i] = lives.clone();
        }
    }
    Analysis {
        reaching,
        live,
        available,
        copies,
        before_definitions,
        before_expressions,
        before_copies,
        live_before,
        live_after
    }
}

mod tac_parser;
mod cfg;
mod dataflow;
mod optimizations;
mod regalloc;
use std::collections::{
    BTreeMap,
    BTreeSet
};
use std::fs;
use tac_parser::{
    Program,
    Function,
    Line,
    Instruction,
    Operand,
    Expression
};
use cfg::Graph;
use dataflow::Analysis;
const PASSES: [&str;
6] = ["constprop", "copyprop", "cse", "dce", "licm", "unreachable"];
const KINDS: [&str;
11] = ["copy", "bin", "load", "store", "goto", "if", "param", "call", "return", "read", "print"];
fn list(values: impl IntoIterator<Item = String>) -> String {
    let values: Vec<String> = values.into_iter().collect();
    if values.is_empty() {
        "-".into()
    } else {
        values.join(",")
    }
}
fn block_list(values: impl IntoIterator<Item = usize>) -> String {
    list(values.into_iter().map(|b| format!("B{}", b + 1)))
}
fn numbers(values: impl IntoIterator<Item = usize>) -> String {
    list(values.into_iter().map(|n| format!("#{}", n + 1)))
}
fn constant(instructions: &[Instruction], definitions: &dataflow::Definitions, variable: &str) -> Option<i64> {
    let definitions: Vec<usize> = definitions.iter().filter(|d| d.0 == variable).map(|d| d.1).collect();
    if definitions.is_empty() || definitions.contains(&0) {
        return None;
    }
    let mut value = None;
    for number in definitions {
        let instruction = &instructions[number - 1];
        if instruction.kind != "copy" {
            return None;
        }
        let current = instruction.a.as_ref()?.constant()?;
        if value.map_or(false, |v| v != current) {
            return None;
        }
        value = Some(current);
    }
    value
}
fn propagate(function: &mut Function, graph: &Graph, analysis: &Analysis, constants: bool) -> (usize, Vec<String>) {
    let instructions = function.instructions();
    let mut replacements = BTreeMap::new();
    let mut records = Vec::new();
    for (i, instruction) in instructions.iter().enumerate() {
        if !graph.reachable.contains(&graph.owners[i]) {
            continue;
        }
        let mut instruction = instruction.clone();
        for operand in instruction.operands_mut() {
            if let Operand::Variable(variable) = operand.clone() {
                let replacement = if constants {
                    constant(&instructions, &analysis.before_definitions[i], &variable).map(Operand::Constant)
                } else {
                    analysis.before_copies[i].iter().find(|p| p.0 == variable).map(|p| Operand::Variable(p.1.clone()))
                };
                if let Some(replacement) = replacement {
                    records.push(format!("#{}: {} -> {}", i + 1, variable, replacement.text()));
                    *operand = replacement;
                }
            }
        }
        if constants {
            if let Some(folded) = optimizations::fold(&instruction) {
                if let Some(folded) = folded {
                    records.push(format!("#{}: fold {}", i + 1, folded.text()));
                    replacements.insert(i, vec![folded]);
                }
                else {
                    records.push(format!("#{}: delete {}", i + 1, instruction.text()));
                    replacements.insert(i, Vec::new());
                }
                continue;
            }
        }
        replacements.insert(i, vec![instruction]);
    }
    optimizations::rewrite(function, &replacements);
    (records.len(), records)
}
fn cse(function: &mut Function, graph: &Graph, analysis: &Analysis) -> (usize, Vec<String>) {
    let instructions = function.instructions();
    let mut groups: BTreeMap<Expression,
    Vec<usize>> = BTreeMap::new();
    for (i, instruction) in instructions.iter().enumerate() {
        if graph.reachable.contains(&graph.owners[i]) {
            if let Some(expression) = instruction.expression() {
                if analysis.before_expressions[i].contains(&expression) {
                    groups.entry(expression).or_default().push(i);
                }
            }
        }
    }
    let mut groups: Vec<_> = groups.into_iter().collect();
    groups.sort_by_key(|g| g.1[0]);
    let mut replacements = BTreeMap::new();
    let mut records = Vec::new();
    let mut count = 0;
    for (expression, candidates) in groups {
        let mut sources = BTreeSet::new();
        for &candidate in &candidates {
            let block = graph.owners[candidate];
            let first = graph.blocks[block].first;
            if let Some(source) = (first..candidate).rev().find(|&i| instructions[i].expression().as_ref() == Some(&expression)) {
                sources.insert(source);
                continue;
            }
            let mut pending: Vec<usize> = graph.blocks[block].predecessors.iter().copied().filter(|p| graph.reachable.contains(p)).collect();
            let mut seen = BTreeSet::new();
            while let Some(block) = pending.pop() {
                if !seen.insert(block) {
                    continue;
                }
                if let Some(source) = (graph.blocks[block].first..=graph.blocks[block].last).rev().find(|&i| instructions[i].expression().as_ref() == Some(&expression)) {
                    sources.insert(source);
                }
                else {
                    pending.extend(graph.blocks[block].predecessors.iter().copied().filter(|p| graph.reachable.contains(p)));
                }
            }
        }
        for candidate in &candidates {
            sources.remove(candidate);
        }
        let temporary = optimizations::temporary(function);
        for &source in &sources {
            replacements.insert(source, optimizations::cse_rewrite(&instructions[source], &temporary, true));
        }
        for &candidate in &candidates {
            replacements.insert(candidate, optimizations::cse_rewrite(&instructions[candidate], &temporary, false));
        }
        records.push(format!("{}: {} sources={} replaced={}", expression.text(), temporary, numbers(sources.iter().copied()), numbers(candidates.iter().copied())));
        count += candidates.len();
    }
    optimizations::rewrite(function, &replacements);
    (count, records)
}
fn dce(function: &mut Function, graph: &Graph, analysis: &Analysis) -> (usize, Vec<String>) {
    let instructions = function.instructions();
    let mut replacements = BTreeMap::new();
    let mut records = BTreeMap::new();
    for &b in &graph.reachable {
        let mut live = analysis.live.output[b].clone();
        for i in (graph.blocks[b].first..=graph.blocks[b].last).rev() {
            let instruction = &instructions[i];
            let destination = instruction.destination.as_ref();
            let self_copy = instruction.kind == "copy" && destination.map(String::as_str) == instruction.a.as_ref().and_then(Operand::variable);
            let dead = ["copy", "bin", "load"].contains(&instruction.kind) && destination.map_or(false, |d| !live.contains(d));
            if self_copy || dead {
                replacements.insert(i, Vec::new());
                records.insert(i, format!("#{}: delete {}", i + 1, instruction.text()));
                continue;
            }
            let mut instruction = instruction.clone();
            if instruction.kind == "call" && destination.map_or(false, |d| !live.contains(d)) {
                records.insert(i, format!("#{}: unused result {}", i + 1, instruction.text()));
                instruction.destination = None;
                replacements.insert(i, vec![instruction.clone()]);
            }
            dataflow::live_transfer(&mut live, &instruction);
        }
    }
    optimizations::rewrite(function, &replacements);
    (records.len(), records.into_iter().map(|e| e.1).collect())
}
fn licm(function: &mut Function, graph: &Graph, analysis: &Analysis) -> (usize, Vec<String>) {
    let instructions = function.instructions();
    let mut loops: Vec<_> = graph.loops.iter().collect();
    loops.sort_by_key(|l| (l.blocks.len(), l.header));
    for natural_loop in loops {
        let inside = |number: usize| number != 0 && natural_loop.blocks.contains(&graph.owners[number - 1]);
        let indices: Vec<usize> = (0..instructions.len()).filter(|&i| natural_loop.blocks.contains(&graph.owners[i])).collect();
        let mut marked = BTreeSet::new();
        let mut mark_order = Vec::new();
        loop {
            let mut changed = false;
            for &i in &indices {
                let instruction = &instructions[i];
                if marked.contains(&i) || !["copy", "bin", "load"].contains(&instruction.kind) {
                    continue;
                }
                if instruction.kind == "load" && indices.iter().any(|&j| instructions[j].kind == "call" || (instructions[j].kind == "store" && instructions[j].array == instruction.array)) {
                    continue;
                }
                let invariant = instruction.used().iter().all(|variable| {
                    let definitions: Vec<usize> = analysis.before_definitions[i].iter().filter(|d| d.0 == *variable).map(|d| d.1).collect();
                    definitions.iter().all(|&n| !inside(n)) || (definitions.len() == 1 && inside(definitions[0]) && marked.contains(&(definitions[0] - 1)))
                });
                if invariant {
                    marked.insert(i);
                    mark_order.push(i);
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
        let mut moved = Vec::new();
        let mut moved_set = BTreeSet::new();
        for i in mark_order {
            let instruction = &instructions[i];
            let destination = instruction.destination.as_ref().unwrap();
            if indices.iter().filter(|&&j| instructions[j].destination.as_ref() == Some(destination)).count() != 1 || analysis.live.input[natural_loop.header].contains(destination) {
                continue;
            }
            let block = graph.owners[i];
            let dominates_exits = natural_loop.exits.iter().all(|exit| graph.dominators[*exit].contains(&block));
            let dangerous = instruction.kind == "load" || (instruction.kind == "bin" && (instruction.operation == "/" || instruction.operation == "%") && instruction.b.as_ref().and_then(Operand::constant).map_or(true, |n| n == 0));
            let safe = !dangerous && natural_loop.outside.iter().all(|&b| !analysis.live.input[b].contains(destination));
            if !dominates_exits && !safe {
                continue;
            }
            if !instruction.used().iter().all(|variable| analysis.before_definitions[i].iter().filter(|d| d.0 == *variable && inside(d.1)).all(|d| moved_set.contains(&(d.1 - 1)))) {
                continue;
            }
            moved.push(i);
            moved_set.insert(i);
        }
        if !moved.is_empty() {
            let target = optimizations::hoist(function, graph, natural_loop, &moved);
            return (moved.len(), vec![format!("B{}: hoist {} to {}", natural_loop.header + 1, numbers(moved), target)]);
        }
    }
    (0, Vec::new())
}
fn pass(name: &str, function: &mut Function) -> (usize, Vec<String>) {
    let graph = cfg::build(function);
    let analysis = dataflow::analyze(function, &graph);
    match name {
        "constprop" => propagate(function, &graph, &analysis, true),
        "copyprop" => propagate(function, &graph, &analysis, false),
        "cse" => cse(function, &graph, &analysis),
        "dce" => dce(function, &graph, &analysis),
        "licm" => licm(function, &graph, &analysis),
        _ => {
            let records = optimizations::unreachable(function, &graph);
            (records.len(), records)
        }
    }
}
struct Calls {
    edges: Vec<Vec<usize>>,
    reachable: BTreeSet<usize>
}
fn reach(start: usize, edges: &[Vec<usize>]) -> BTreeSet<usize> {
    let mut pending = vec![start];
    let mut seen = BTreeSet::new();
    while let Some(i) = pending.pop() {
        if seen.insert(i) {
            pending.extend(edges[i].iter().copied());
        }
    }
    seen
}
fn call_graph(program: &Program) -> Calls {
    let indices: BTreeMap<String,
    usize> = program.functions.iter().enumerate().map(|(i, f)| (f.name.clone(), i)).collect();
    let edges: Vec<Vec<usize>> = program.functions.iter().map(|f| {
        let mut callees = BTreeSet::new();
        for instruction in f.instructions() {
            if instruction.kind == "call" {
                callees.insert(indices[&instruction.function]);
            }
        }
        callees.into_iter().collect()
    }).collect();
    let reachable = reach(indices["main"], &edges);
    Calls {
        edges,
        reachable
    }
}
fn graph_report(program: &Program, graph: &Calls, label: &str, output: &mut Vec<String>) {
    output.push(format!("== call graph ({}) ==", label));
    for (i, function) in program.functions.iter().enumerate() {
        let recursive = graph.edges[i].iter().any(|&j| reach(j, &graph.edges).contains(&i));
        output.push(format!("{} -> {}{}", function.name, list(graph.edges[i].iter().map(|&j| program.functions[j].name.clone())), if recursive {
            " (recursive)"
        } else {
            ""
        }));
    }
    output.push(format!("unreachable functions: {}", list(program.functions.iter().enumerate().filter(|e| !graph.reachable.contains(&e.0)).map(|e| e.1.name.clone()))));
}
fn definition_list(definitions: &dataflow::Definitions) -> String {
    let mut definitions: Vec<_> = definitions.iter().collect();
    definitions.sort_by(|a, b| a.1.cmp(&b.1).then_with(|| a.0.cmp(&b.0)));
    list(definitions.into_iter().map(|(v, n)| format!("{}:{}", v, n)))
}
fn dominator_tree(block: usize, depth: usize, graph: &Graph, output: &mut Vec<String>) {
    output.push(format!("{}B{}", " ".repeat(depth * 2), block + 1));
    for b in 0..graph.blocks.len() {
        if graph.idom[b] == Some(block) {
            dominator_tree(b, depth + 1, graph, output);
        }
    }
}
fn analysis_report(function: &Function, label: &str, output: &mut Vec<String>) {
    let graph = cfg::build(function);
    let analysis = dataflow::analyze(function, &graph);
    output.push(format!("== {} ({}) ==", function.name, label));
    output.push("code:".into());
    let mut number = 0;
    for line in &function.code {
        match line {
            Line::Label(label) => output.push(format!("{}:", label)),
            Line::Instruction(instruction) => {
                let mut text = format!("  #{} {}", number + 1, instruction.text());
                if graph.reachable.contains(&graph.owners[number]) {
                    let mut used = BTreeSet::new();
                    let mut chains = Vec::new();
                    for variable in instruction.used() {
                        if used.insert(variable.clone()) {
                            let mut definitions: Vec<usize> = analysis.before_definitions[number].iter().filter(|d| d.0 == variable).map(|d| d.1).collect();
                            definitions.sort();
                            chains.push(format!("{}:{}", variable, list(definitions.into_iter().map(|n| n.to_string()))));
                        }
                    }
                    if !chains.is_empty() {
                        text.push_str(&format!(" | {}", chains.join(" ")));
                    }
                }
                output.push(text);
                number += 1;
            }
        }
    }
    output.push(format!("blocks: {}", graph.blocks.len()));
    for (b, block) in graph.blocks.iter().enumerate() {
        output.push(format!("B{} {}-{} labels={} preds={} succs={}", b + 1, block.first + 1, block.last + 1, list(block.labels.iter().cloned()), block_list(block.predecessors.iter().copied()), block_list(block.successors.iter().copied())));
    }
    output.push(format!("unreachable: {}", block_list((0..graph.blocks.len()).filter(|b| !graph.reachable.contains(b)))));
    output.push(format!("order: {}", block_list(graph.order.iter().copied())));
    output.push("dominators:".into());
    for &b in &graph.reachable {
        output.push(format!("B{} idom={} dom={}", b + 1, graph.idom[b].map_or("-".into(), |p| format!("B{}", p + 1)), block_list(graph.dominators[b].iter().copied())));
    }
    output.push("dominator tree:".into());
    dominator_tree(0, 0, &graph, output);
    output.push(format!("loops: {}", graph.loops.len()));
    for natural_loop in &graph.loops {
        output.push(format!("header=B{} latches={} depth={} blocks={} exits={}", natural_loop.header + 1, block_list(natural_loop.latches.iter().copied()), natural_loop.depth, block_list(natural_loop.blocks.iter().copied()), block_list(natural_loop.exits.iter().copied())));
    }
    output.push(format!("reaching definitions: iterations={}", analysis.reaching.iterations));
    for &b in &graph.reachable {
        output.push(format!("B{} in={} out={}", b + 1, definition_list(&analysis.reaching.input[b]), definition_list(&analysis.reaching.output[b])));
    }
    output.push(format!("liveness: iterations={}", analysis.live.iterations));
    for &b in &graph.reachable {
        output.push(format!("B{} in={} out={}", b + 1, list(analysis.live.input[b].iter().cloned()), list(analysis.live.output[b].iter().cloned())));
    }
    output.push(format!("available expressions: iterations={}", analysis.available.iterations));
    for &b in &graph.reachable {
        let strings = |set: &BTreeSet<Expression>| {
            let mut strings: Vec<String> = set.iter().map(Expression::text).collect();
            strings.sort();
            list(strings)
        };
        output.push(format!("B{} in={} out={}", b + 1, strings(&analysis.available.input[b]), strings(&analysis.available.output[b])));
    }
}
fn allocate(function: &Function, registers: usize, output: &mut Vec<String>) -> Function {
    let graph = cfg::build(function);
    let analysis = dataflow::analyze(function, &graph);
    let allocation = regalloc::allocate(function, &graph, &analysis, registers);
    let mut allocated = function.clone();
    let mut moves = 0;
    let rewrite = |name: &str| allocation.registers.get(name).copied().flatten().map_or(name.to_string(), |r| format!("R{}", r));
    for parameter in &mut allocated.parameters {
        *parameter = rewrite(parameter);
    }
    for line in &mut allocated.code {
        if let Line::Instruction(instruction) = line {
            if let Some(destination) = &mut instruction.destination {
                *destination = rewrite(destination);
            }
            for operand in instruction.operands_mut() {
                if let Operand::Variable(name) = operand {
                    *name = rewrite(name);
                }
            }
        }
    }
    allocated.code.retain(|line| {
        if let Line::Instruction(instruction) = line {
            if instruction.kind == "copy" && instruction.destination.as_deref() == instruction.a.as_ref().and_then(Operand::variable) {
                moves += 1;
                return false;
            }
        }
        true
    });
    let spilled: BTreeSet<String> = allocation.registers.iter().filter(|e| e.1.is_none()).map(|e| e.0.clone()).collect();
    let mut spill_uses = 0;
    let mut spill_defs = function.parameters.iter().filter(|p| spilled.contains(*p)).count();
    for instruction in function.instructions() {
        spill_uses += instruction.used().iter().filter(|v| spilled.contains(*v)).count();
        if instruction.destination.as_ref().map_or(false, |d| spilled.contains(d)) {
            spill_defs += 1;
        }
    }
    let pressure = (0..graph.owners.len()).filter(|&i| graph.reachable.contains(&graph.owners[i])).flat_map(|i| [analysis.live_before[i].len(), analysis.live_after[i].len()].to_vec()).max().unwrap_or(0);
    let used: BTreeSet<usize> = allocation.registers.values().copied().flatten().collect();
    output.push(format!("== {} ==", function.name));
    output.push(format!("nodes={} edges={} registers={}", allocation.neighbors.len(), allocation.neighbors.values().map(BTreeSet::len).sum::<usize>() / 2, registers));
    for (node, neighbors) in &allocation.neighbors {
        output.push(format!("{} degree={} cost={} neighbors={}", node, neighbors.len(), allocation.costs[node], list(neighbors.iter().cloned())));
    }
    output.push(format!("simplify: {}", list(allocation.order.iter().cloned())));
    output.push(format!("potential spills: {}", list(allocation.potentials.iter().map(|(name, degree)| format!("{}({}/{})", name, allocation.costs[name], degree)))));
    for (name, assigned) in &allocation.registers {
        output.push(format!("{} -> {}", name, assigned.map_or("spill".into(), |r| format!("R{}", r))));
    }
    output.push(format!("summary: pressure={} used={} spilled={} moves={} spill_uses={} spill_defs={}", pressure, used.len(), spilled.len(), moves, spill_uses, spill_defs));
    output.extend(allocated.text());
    allocated
}
struct Execution<'a> {
    program: &'a Program,
    arrays: BTreeMap<String,
    Vec<i64>>,
    input: &'a [i64],
    position: usize,
    output: Vec<i64>,
    steps: BTreeMap<String,
    usize>,
    calls: BTreeMap<String,
    usize>,
    kinds: BTreeMap<&'static str,
    usize>
}
impl<'a> Execution<'a> {
    fn new(program: &'a Program, input: &'a [i64]) -> Self {
        Self {
            program,
            arrays: program.arrays.iter().map(|(a, n)| (a.clone(), vec![0; *n])).collect(),
            input,
            position: 0,
            output: Vec::new(),
            steps: BTreeMap::new(),
            calls: BTreeMap::new(),
            kinds: KINDS.iter().map(|&k| (k, 0)).collect()
        }
    }
    fn value(operand: &Operand, values: &BTreeMap<String, i64>) -> i64 {
        match operand {
            Operand::Constant(n) => *n,
            Operand::Variable(name) => values[name]
        }
    }
    fn call(&mut self, name: &str, arguments: Vec<i64>) -> Option<i64> {
        *self.calls.entry(name.into()).or_insert(0) += 1;
        let function = self.program.functions.iter().find(|f| f.name == name).unwrap().clone();
        let instructions = function.instructions();
        let labels = tac_parser::labels(&function);
        let mut values: BTreeMap<String,
        i64> = function.parameters.iter().cloned().zip(arguments).collect();
        let mut pushed = Vec::new();
        let mut pc = 0;
        loop {
            let instruction = &instructions[pc];
            *self.steps.entry(name.into()).or_insert(0) += 1;
            *self.kinds.get_mut(instruction.kind).unwrap() += 1;
            let mut next = pc + 1;
            let a = instruction.a.as_ref().map(|a| Self::value(a, &values));
            let b = instruction.b.as_ref().map(|b| Self::value(b, &values));
            let mut result = None;
            match instruction.kind {
                "copy" => result = a,
                "bin" => result = Some(tac_parser::operation(&instruction.operation, a.unwrap(), b.unwrap())),
                "load" => result = Some(self.arrays[&instruction.array][a.unwrap() as usize]),
                "store" => self.arrays.get_mut(&instruction.array).unwrap()[a.unwrap() as usize] = b.unwrap(),
                "goto" => next = labels[&instruction.target],
                "if" => if tac_parser::operation(&instruction.operation, a.unwrap(), b.unwrap()) != 0 {
                    next = labels[&instruction.target];
                },
                "param" => pushed.push(a.unwrap()),
                "call" => {
                    let arguments = pushed.split_off(pushed.len() - instruction.count);
                    result = self.call(&instruction.function, arguments);
                },
                "return" => return a,
                "read" => {
                    result = Some(self.input[self.position]);
                    self.position += 1;
                },
                "print" => self.output.push(a.unwrap()),
                _ => unreachable!()
            }
            if let (Some(destination), Some(value)) = (&instruction.destination, result) {
                values.insert(destination.clone(), value);
            }
            pc = next;
        }
    }
}
fn kind_counts(program: &Program) -> BTreeMap<&'static str, usize> {
    let mut counts: BTreeMap<&str,
    usize> = KINDS.iter().map(|&k| (k, 0)).collect();
    for function in &program.functions {
        for instruction in function.instructions() {
            *counts.get_mut(instruction.kind).unwrap() += 1;
        }
    }
    counts
}
fn write(name: &str, lines: &[String]) {
    fs::create_dir_all("output").unwrap();
    fs::write(format!("output/{}", name), if lines.is_empty() {
        String::new()
    } else {
        lines.join("\n") + "\n"
    }).unwrap();
}
fn main() {
    let original = tac_parser::parse(&fs::read_to_string("input/program.tac").unwrap());
    let parameters = fs::read_to_string("input/params.txt").unwrap();
    let settings: Vec<Vec<&str>> = parameters.lines().map(|l| l.split(' ').collect()).collect();
    let registers = settings[0][1].parse().unwrap();
    let enabled: Vec<&str> = PASSES.iter().copied().filter(|p| settings[1][1..].contains(p)).collect();
    let rounds: usize = settings[2][1].parse().unwrap();
    let mut optimized = original.clone();
    let mut passes = Vec::new();
    let mut totals: BTreeMap<&str,
    usize> = enabled.iter().map(|&p| (p, 0)).collect();
    for function in &mut optimized.functions {
        let before = function.instructions().len();
        passes.push(format!("== {} ==", function.name));
        let mut performed = 0;
        for round in 1..=rounds {
            performed = round;
            let mut changes = Vec::new();
            let mut records = Vec::new();
            let mut changed = false;
            for &name in &enabled {
                let (count, entries) = pass(name, function);
                changed |= count > 0;
                changes.push(format!("{}={}", name, count));
                *totals.get_mut(name).unwrap() += count;
                for entry in entries {
                    records.push(format!("  {} {}", name, entry));
                }
            }
            passes.push(format!("round {}: {}", round, changes.join(" ")));
            passes.extend(records);
            if !changed {
                break;
            }
        }
        passes.push(format!("result: rounds={} instructions={}->{}", performed, before, function.instructions().len()));
    }
    let optimized_graph = call_graph(&optimized);
    let mut analysis = Vec::new();
    graph_report(&original, &call_graph(&original), "original", &mut analysis);
    for function in &original.functions {
        analysis_report(function, "original", &mut analysis);
    }
    graph_report(&optimized, &optimized_graph, "optimized", &mut analysis);
    let removed = if enabled.contains(&"unreachable") {
        optimized.functions.iter().enumerate().filter(|e| !optimized_graph.reachable.contains(&e.0)).map(|e| e.1.name.clone()).collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    optimized.functions.retain(|f| !removed.contains(&f.name));
    for function in &optimized.functions {
        analysis_report(function, "optimized", &mut analysis);
    }
    passes.push("== program ==".into());
    passes.push(format!("removed functions: {}", list(removed)));
    passes.push("== total ==".into());
    passes.push(enabled.iter().map(|p| format!("{}={}", p, totals[p])).collect::<Vec<_>>().join(" "));
    let mut regalloc = Vec::new();
    let allocated = Program {
        arrays: optimized.arrays.clone(),
        functions: optimized.functions.iter().map(|f| allocate(f, registers, &mut regalloc)).collect()
    };
    let input = fs::read_to_string("input/input.txt").unwrap();
    let runs: Vec<Vec<i64>> = input.lines().skip(1).map(|l| l.split_whitespace().skip(1).map(|v| v.parse().unwrap()).collect()).collect();
    let programs = [&original, &optimized, &allocated];
    let labels = ["original", "optimized", "allocated"];
    let mut comparison = Vec::new();
    let mut same = 0;
    let mut total_steps = [0usize; 3];
    let mut profile_steps: Vec<BTreeMap<String,
    usize>> = vec![BTreeMap::new(); 3];
    let mut profile_calls: BTreeMap<String,
    usize> = BTreeMap::new();
    let mut dynamic: Vec<BTreeMap<&str,
    usize>> = (0..3).map(|_| KINDS.iter().map(|&k| (k, 0)).collect()).collect();
    for (i, input) in runs.iter().enumerate() {
        comparison.push(format!("run {}: inputs={}", i + 1, input.len()));
        let mut outputs = Vec::new();
        for p in 0..3 {
            let mut execution = Execution::new(programs[p], input);
            execution.call("main", Vec::new());
            let steps: usize = execution.steps.values().sum();
            let calls: usize = execution.calls.values().sum();
            comparison.push(format!("  {}: steps={} calls={} output={}", labels[p], steps, calls, list(execution.output.iter().map(ToString::to_string))));
            outputs.push(execution.output);
            total_steps[p] += steps;
            for (name, steps) in execution.steps {
                *profile_steps[p].entry(name).or_insert(0) += steps;
            }
            if p == 0 {
                for (name, count) in execution.calls {
                    *profile_calls.entry(name).or_insert(0) += count;
                }
            }
            for (kind, count) in execution.kinds {
                *dynamic[p].get_mut(kind).unwrap() += count;
            }
        }
        let equal = outputs[0] == outputs[1] && outputs[0] == outputs[2];
        if equal {
            same += 1;
        }
        comparison.push(format!("  result: {}", if equal {
            "same"
        } else {
            "different"
        }));
    }
    comparison.push("== profile ==".into());
    for function in &original.functions {
        let name = &function.name;
        comparison.push(format!("{}: calls={} original={} optimized={} allocated={}", name, profile_calls.get(name).unwrap_or(&0), profile_steps[0].get(name).unwrap_or(&0), profile_steps[1].get(name).unwrap_or(&0), profile_steps[2].get(name).unwrap_or(&0)));
    }
    let before = kind_counts(&original);
    let after = kind_counts(&optimized);
    comparison.push("== summary ==".into());
    comparison.push(format!("runs={} same={} different={}", runs.len(), same, runs.len() - same));
    comparison.push(format!("instructions: original={} optimized={}", before.values().sum::<usize>(), after.values().sum::<usize>()));
    comparison.push(format!("kinds: {}", KINDS.iter().map(|k| format!("{}={}->{}", k, before[k], after[k])).collect::<Vec<_>>().join(" ")));
    comparison.push(format!("steps: original={} optimized={} allocated={}", total_steps[0], total_steps[1], total_steps[2]));
    for p in 0..3 {
        comparison.push(format!("dynamic {}: {}", labels[p], KINDS.iter().map(|k| format!("{}={}", k, dynamic[p][k])).collect::<Vec<_>>().join(" ")));
    }
    write("optimized.tac", &optimized.text());
    write("analysis.txt", &analysis);
    write("passes.txt", &passes);
    write("regalloc.txt", &regalloc);
    write("comparison.txt", &comparison);
}

use std::collections::{
    BTreeMap,
    BTreeSet
};
use crate::tac_parser::{
    Function,
    Instruction,
    Operand,
    Line
};
use crate::cfg::{
    Graph,
    Loop
};
pub fn fold(instruction: &Instruction) -> Option<Option<Instruction>> {
    if instruction.kind != "bin" && instruction.kind != "if" {
        return None;
    }
    let a = instruction.a.as_ref().unwrap();
    let b = instruction.b.as_ref().unwrap();
    if let (Some(a), Some(b)) = (a.constant(), b.constant()) {
        if (instruction.operation == "/" || instruction.operation == "%") && b == 0 {
            return None;
        }
        let value = crate::tac_parser::operation(&instruction.operation, a, b);
        if instruction.kind == "if" {
            if value == 0 {
                return Some(None);
            }
            let mut jump = Instruction::new("goto");
            jump.target = instruction.target.clone();
            return Some(Some(jump));
        }
        if !(-2147483648..=2147483647).contains(&value) {
            return None;
        }
        return Some(Some(Instruction::copy(instruction.destination.clone().unwrap(), Operand::Constant(value))));
    }
    if instruction.kind != "bin" {
        return None;
    }
    let value = match instruction.operation.as_str() {
        "+" if a.constant() == Some(0) => Some(b.clone()),
        "+" | "-" if b.constant() == Some(0) => Some(a.clone()),
        "*" if a.constant() == Some(1) => Some(b.clone()),
        "*" | "/" if b.constant() == Some(1) => Some(a.clone()),
        "*" if a.constant() == Some(0) || b.constant() == Some(0) => Some(Operand::Constant(0)),
        _ => None
    };
    value.map(|value| Some(Instruction::copy(instruction.destination.clone().unwrap(), value)))
}
pub fn rewrite(function: &mut Function, replacements: &BTreeMap<usize, Vec<Instruction>>) {
    let mut code = Vec::new();
    let mut number = 0;
    for line in &function.code {
        match line {
            Line::Label(_) => code.push(line.clone()),
            Line::Instruction(instruction) => {
                if let Some(replacement) = replacements.get(&number) {
                    code.extend(replacement.iter().cloned().map(Line::Instruction));
                } else {
                    code.push(Line::Instruction(instruction.clone()));
                }
                number += 1;
            }
        }
    }
    function.code = code;
}
pub fn temporary(function: &mut Function) -> String {
    function.temporary += 1;
    format!("_t{}", function.temporary)
}
pub fn cse_rewrite(instruction: &Instruction, temporary: &str, source: bool) -> Vec<Instruction> {
    let destination = instruction.destination.clone().unwrap();
    let copy = Instruction::copy(destination, Operand::Variable(temporary.into()));
    if source {
        let mut calculation = instruction.clone();
        calculation.destination = Some(temporary.into());
        vec![calculation, copy]
    } else {
        vec![copy]
    }
}
pub fn hoist(function: &mut Function, graph: &Graph, natural_loop: &Loop, moved: &[usize]) -> String {
    let header = natural_loop.header;
    let outside: Vec<usize> = graph.blocks[header].predecessors.iter().copied().filter(|p| !natural_loop.blocks.contains(p)).collect();
    let preheader = if header != 0 && outside.len() == 1 && graph.blocks[outside[0]].successors == vec![header] {
        Some(outside[0])
    } else {
        None
    };
    let mut positions = Vec::new();
    for (i, line) in function.code.iter().enumerate() {
        if matches!(line, Line::Instruction(_)) {
            positions.push(i);
        }
    }
    let instructions = function.instructions();
    let moving: BTreeSet<usize> = moved.iter().copied().collect();
    let mut insertion = Vec::new();
    let position;
    let target;
    if let Some(preheader) = preheader {
        let last = graph.blocks[preheader].last;
        position = positions[last] + if instructions[last].kind == "goto" || instructions[last].kind == "if" {
            0
        } else {
            1
        };
        target = format!("B{}", preheader + 1);
    } else {
        function.preheader += 1;
        let label = format!("_p{}", function.preheader);
        target = format!("new {}", label);
        insertion.push(Line::Label(label.clone()));
        let mut first = positions[graph.blocks[header].first];
        while first > 0 && matches!(function.code[first - 1], Line::Label(_)) {
            first -= 1;
        }
        position = first;
        for &p in &outside {
            let index = graph.blocks[p].last;
            if (instructions[index].kind == "goto" || instructions[index].kind == "if") && graph.blocks[header].labels.contains(&instructions[index].target) {
                if let Line::Instruction(instruction) = &mut function.code[positions[index]] {
                    instruction.target = label.clone();
                }
            }
        }
    }
    insertion.extend(moved.iter().map(|&i| Line::Instruction(instructions[i].clone())));
    let mut code = Vec::new();
    let mut number = 0;
    for (i, line) in function.code.iter().enumerate() {
        if i == position {
            code.extend(insertion.iter().cloned());
        }
        match line {
            Line::Label(_) => code.push(line.clone()),
            Line::Instruction(_) => {
                if !moving.contains(&number) {
                    code.push(line.clone());
                }
                number += 1;
            }
        }
    }
    if position == function.code.len() {
        code.extend(insertion);
    }
    function.code = code;
    target
}
pub fn unreachable(function: &mut Function, graph: &Graph) -> Vec<String> {
    let mut records = Vec::new();
    for b in 0..graph.blocks.len() {
        if !graph.reachable.contains(&b) {
            records.push(format!("remove block B{}", b + 1));
        }
    }
    let mut code = Vec::new();
    let mut number = 0;
    let mut labels = Vec::new();
    for line in &function.code {
        match line {
            Line::Label(_) => labels.push(line.clone()),
            Line::Instruction(_) => {
                if graph.reachable.contains(&graph.owners[number]) {
                    code.append(&mut labels);
                    code.push(line.clone());
                } else {
                    labels.clear();
                }
                number += 1;
            }
        }
    }
    let mut delete = BTreeSet::new();
    let mut number = 0;
    for (i, line) in code.iter().enumerate() {
        if let Line::Instruction(instruction) = line {
            number += 1;
            if instruction.kind == "goto" || instruction.kind == "if" {
                let following: Vec<String> = code[i + 1..].iter().take_while(|l| matches!(l, Line::Label(_))).filter_map(|l| if let Line::Label(label) = l {
                    Some(label.clone())
                } else {
                    None
                }).collect();
                if following.contains(&instruction.target) {
                    delete.insert(i);
                    records.push(format!("remove jump #{}", number));
                }
            }
        }
    }
    code = code.into_iter().enumerate().filter_map(|(i, l)| if delete.contains(&i) {
        None
    } else {
        Some(l)
    }).collect();
    let targets: BTreeSet<String> = code.iter().filter_map(|l| if let Line::Instruction(instruction) = l {
        if instruction.kind == "goto" || instruction.kind == "if" {
            Some(instruction.target.clone())
        } else {
            None
        }
    } else {
        None
    }).collect();
    code.retain(|line| if let Line::Label(label) = line {
        if !targets.contains(label) {
            records.push(format!("remove label {}", label));
            false
        } else {
            true
        }
    } else {
        true
    });
    function.code = code;
    records
}

use std::collections::{
    BTreeMap,
    BTreeSet
};
use std::cmp::Ordering;
use std::fmt;
use crate::tac_parser::Function;
use crate::cfg::Graph;
use crate::dataflow::{
    Analysis,
    live_transfer
};
#[derive(Clone, Eq, PartialEq)]
pub struct Cost(Vec<u32>);
impl Cost {
    fn zero() -> Self {
        Self(vec![0])
    }
    fn power(exponent: usize) -> Self {
        let mut digits = vec![0; exponent / 9 + 1];
        digits[exponent / 9] = 10u32.pow((exponent % 9) as u32);
        Self(digits)
    }
    fn add(&mut self, other: &Self) {
        let mut carry = 0u64;
        self.0.resize(self.0.len().max(other.0.len()), 0);
        for i in 0..self.0.len() {
            let sum = self.0[i] as u64 + other.0.get(i).copied().unwrap_or(0) as u64 + carry;
            self.0[i] = (sum % 1000000000) as u32;
            carry = sum / 1000000000;
        }
        if carry > 0 {
            self.0.push(carry as u32);
        }
    }
    fn multiply(&self, factor: usize) -> Self {
        let mut result = Self::zero();
        result.0.clear();
        let mut carry = 0u64;
        for &digit in &self.0 {
            let value = digit as u64 * factor as u64 + carry;
            result.0.push((value % 1000000000) as u32);
            carry = value / 1000000000;
        }
        while carry > 0 {
            result.0.push((carry % 1000000000) as u32);
            carry /= 1000000000;
        }
        while result.0.len() > 1 && result.0.last() == Some(&0) {
            result.0.pop();
        }
        result
    }
}
impl Ord for Cost {
    fn cmp(&self, other: &Self) -> Ordering {
        self.0.len().cmp(&other.0.len()).then_with(|| self.0.iter().rev().cmp(other.0.iter().rev()))
    }
}
impl PartialOrd for Cost {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl fmt::Display for Cost {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.0.last().unwrap())?;
        for digit in self.0.iter().rev().skip(1) {
            write!(f, "{:09}", digit)?;
        }
        Ok(())
    }
}
pub struct Allocation {
    pub neighbors: BTreeMap<String,
    BTreeSet<String>>,
    pub costs: BTreeMap<String,
    Cost>,
    pub order: Vec<String>,
    pub potentials: Vec<(String, usize)>,
    pub registers: BTreeMap<String,
    Option<usize>>
}
fn edge(graph: &mut BTreeMap<String, BTreeSet<String>>, a: &str, b: &str) {
    if a != b {
        graph.get_mut(a).unwrap().insert(b.into());
        graph.get_mut(b).unwrap().insert(a.into());
    }
}
pub fn allocate(function: &Function, graph: &Graph, analysis: &Analysis, count: usize) -> Allocation {
    let instructions = function.instructions();
    let mut nodes: BTreeSet<String> = function.parameters.iter().cloned().collect();
    for (i, instruction) in instructions.iter().enumerate() {
        if graph.reachable.contains(&graph.owners[i]) {
            nodes.extend(instruction.destination.iter().cloned());
            nodes.extend(instruction.used());
        }
    }
    let mut neighbors: BTreeMap<String,
    BTreeSet<String>> = nodes.iter().map(|n| (n.clone(), BTreeSet::new())).collect();
    let mut costs: BTreeMap<String,
    Cost> = nodes.iter().map(|n| (n.clone(), Cost::zero())).collect();
    let mut partners: BTreeMap<String,
    BTreeSet<String>> = neighbors.clone();
    for &b in &graph.reachable {
        let weight = Cost::power(graph.depths[b]);
        let mut live = analysis.live.output[b].clone();
        for i in (graph.blocks[b].first..=graph.blocks[b].last).rev() {
            let instruction = &instructions[i];
            for variable in instruction.destination.iter().cloned().chain(instruction.used()) {
                costs.get_mut(&variable).unwrap().add(&weight);
            }
            if let Some(destination) = &instruction.destination {
                let source = if instruction.kind == "copy" {
                    instruction.a.as_ref().and_then(|a| a.variable())
                } else {
                    None
                };
                for other in &live {
                    if source != Some(other.as_str()) {
                        edge(&mut neighbors, destination, other);
                    }
                }
            }
            live_transfer(&mut live, instruction);
        }
    }
    let parameter_live: BTreeSet<String> = analysis.live.input[0].iter().cloned().chain(function.parameters.iter().cloned()).collect();
    for parameter in &function.parameters {
        costs.get_mut(parameter).unwrap().add(&Cost::power(0));
        for other in &parameter_live {
            edge(&mut neighbors, parameter, other);
        }
    }
    for instruction in &instructions {
        if instruction.kind == "copy" {
            if let (Some(destination), Some(source)) = (&instruction.destination, instruction.a.as_ref().and_then(|a| a.variable())) {
                if destination != source && nodes.contains(destination) && nodes.contains(source) {
                    partners.get_mut(destination).unwrap().insert(source.into());
                    partners.get_mut(source).unwrap().insert(destination.clone());
                }
            }
        }
    }
    let mut remaining = nodes.clone();
    let mut order = Vec::new();
    let mut potentials = Vec::new();
    while !remaining.is_empty() {
        let degrees: BTreeMap<String,
        usize> = remaining.iter().map(|n| (n.clone(), neighbors[n].intersection(&remaining).count())).collect();
        let low = remaining.iter().filter(|n| degrees[*n] < count).min_by(|a, b| degrees[*a].cmp(&degrees[*b]).then_with(|| a.cmp(b))).cloned();
        let chosen = if let Some(low) = low {
            low
        } else {
            let chosen = remaining.iter().min_by(|a, b| costs[*a].multiply(degrees[*b]).cmp(&costs[*b].multiply(degrees[*a])).then_with(|| a.cmp(b))).unwrap().clone();
            potentials.push((chosen.clone(), degrees[&chosen]));
            chosen
        };
        remaining.remove(&chosen);
        order.push(chosen);
    }
    let mut registers: BTreeMap<String,
    Option<usize>> = BTreeMap::new();
    for node in order.iter().rev() {
        let taken: BTreeSet<usize> = neighbors[node].iter().filter_map(|n| registers.get(n).copied().flatten()).collect();
        let free: BTreeSet<usize> = (0..count).filter(|r| !taken.contains(r)).collect();
        let bias = partners[node].iter().filter_map(|n| registers.get(n).copied().flatten()).filter(|r| free.contains(r)).min();
        let assigned = bias.or_else(|| free.iter().next().copied());
        registers.insert(node.clone(), assigned);
    }
    Allocation {
        neighbors,
        costs,
        order,
        potentials,
        registers
    }
}

use std::collections::BTreeMap;
#[derive(Clone, PartialEq, Eq, PartialOrd, Ord)]
pub enum Operand {
    Constant(i64),
    Variable(String)
}
impl Operand {
    pub fn parse(text: &str) -> Self {
        if text.starts_with('-') || text.as_bytes()[0].is_ascii_digit() {
            Self::Constant(text.parse().unwrap())
        } else {
            Self::Variable(text.into())
        }
    }
    pub fn text(&self) -> String {
        match self {
            Self::Constant(n) => n.to_string(),
            Self::Variable(s) => s.clone()
        }
    }
    pub fn variable(&self) -> Option<&str> {
        if let Self::Variable(s) = self {
            Some(s)
        } else {
            None
        }
    }
    pub fn constant(&self) -> Option<i64> {
        if let Self::Constant(n) = self {
            Some(*n)
        } else {
            None
        }
    }
}
#[derive(Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct Expression {
    pub kind: &'static str,
    pub operation: String,
    pub a: Operand,
    pub b: Option<Operand>
}
impl Expression {
    pub fn text(&self) -> String {
        if self.kind == "load" {
            format!("{}[{}]", self.operation, self.a.text())
        } else {
            format!("{}{}{}", self.a.text(), self.operation, self.b.as_ref().unwrap().text())
        }
    }
    pub fn uses(&self, name: &str) -> bool {
        self.a.variable() == Some(name) || self.b.as_ref().and_then(Operand::variable) == Some(name)
    }
}
#[derive(Clone)]
pub struct Instruction {
    pub kind: &'static str,
    pub destination: Option<String>,
    pub a: Option<Operand>,
    pub b: Option<Operand>,
    pub operation: String,
    pub target: String,
    pub array: String,
    pub function: String,
    pub count: usize
}
impl Instruction {
    pub fn new(kind: &'static str) -> Self {
        Self {
            kind,
            destination: None,
            a: None,
            b: None,
            operation: String::new(),
            target: String::new(),
            array: String::new(),
            function: String::new(),
            count: 0
        }
    }
    pub fn copy(destination: String, a: Operand) -> Self {
        let mut instruction = Self::new("copy");
        instruction.destination = Some(destination);
        instruction.a = Some(a);
        instruction
    }
    pub fn operands(&self) -> Vec<&Operand> {
        self.a.iter().chain(self.b.iter()).collect()
    }
    pub fn operands_mut(&mut self) -> Vec<&mut Operand> {
        self.a.iter_mut().chain(self.b.iter_mut()).collect()
    }
    pub fn used(&self) -> Vec<String> {
        self.operands().into_iter().filter_map(|o| o.variable().map(str::to_string)).collect()
    }
    pub fn expression(&self) -> Option<Expression> {
        if self.kind == "bin" || self.kind == "load" {
            Some(Expression {
                kind: self.kind,
                operation: if self.kind == "bin" {
                    self.operation.clone()
                } else {
                    self.array.clone()
                },
                a: self.a.clone().unwrap(),
                b: self.b.clone()
            })
        } else {
            None
        }
    }
    pub fn text(&self) -> String {
        let a = self.a.as_ref().map(Operand::text).unwrap_or_default();
        let b = self.b.as_ref().map(Operand::text).unwrap_or_default();
        let destination = self.destination.as_deref().unwrap_or("");
        match self.kind {
            "copy" => format!("{} = {}", destination, a),
            "bin" => format!("{} = {} {} {}", destination, a, self.operation, b),
            "load" => format!("{} = {}[{}]", destination, self.array, a),
            "store" => format!("{}[{}] = {}", self.array, a, b),
            "goto" => format!("goto {}", self.target),
            "if" => format!("if {} {} {} goto {}", a, self.operation, b, self.target),
            "param" | "print" => format!("{} {}", self.kind, a),
            "read" => format!("read {}", destination),
            "return" => if self.a.is_some() {
                format!("return {}", a)
            } else {
                "return".into()
            },
            "call" => format!("{}call {} {}", if self.destination.is_some() {
                format!("{} = ", destination)
            } else {
                String::new()
            }, self.function, self.count),
            _ => unreachable!()
        }
    }
}
#[derive(Clone)]
pub enum Line {
    Label(String),
    Instruction(Instruction)
}
#[derive(Clone)]
pub struct Function {
    pub name: String,
    pub parameters: Vec<String>,
    pub code: Vec<Line>,
    pub temporary: usize,
    pub preheader: usize
}
impl Function {
    pub fn instructions(&self) -> Vec<Instruction> {
        self.code.iter().filter_map(|l| if let Line::Instruction(i) = l {
            Some(i.clone())
        } else {
            None
        }).collect()
    }
    pub fn text(&self) -> Vec<String> {
        let mut lines = vec![format!("func {}{}", self.name, self.parameters.iter().map(|p| format!(" {}", p)).collect::<Vec<_>>().join(""))];
        for line in &self.code {
            lines.push(match line {
                Line::Label(label) => format!("{}:", label),
                Line::Instruction(i) => format!("    {}", i.text())
            });
        }
        lines.push("end".into());
        lines
    }
}
#[derive(Clone)]
pub struct Program {
    pub arrays: Vec<(String, usize)>,
    pub functions: Vec<Function>
}
impl Program {
    pub fn text(&self) -> Vec<String> {
        let mut lines: Vec<String> = self.arrays.iter().map(|(a, n)| format!("array {} {}", a, n)).collect();
        for function in &self.functions {
            if !lines.is_empty() {
                lines.push(String::new());
            }
            lines.extend(function.text());
        }
        lines
    }
}
fn indexed(text: &str) -> (String, Operand) {
    let open = text.find('[').unwrap();
    (text[..open].into(), Operand::parse(&text[open + 1..text.len() - 1]))
}
pub fn parse(text: &str) -> Program {
    let mut program = Program {
        arrays: Vec::new(),
        functions: Vec::new()
    };
    for line in text.lines() {
        let words: Vec<&str> = line.split_whitespace().collect();
        if words.is_empty() || words[0].starts_with('#') {
            continue;
        }
        if words[0] == "array" {
            program.arrays.push((words[1].into(), words[2].parse().unwrap()));
            continue;
        }
        if words[0] == "func" {
            program.functions.push(Function {
                name: words[1].into(),
                parameters: words[2..].iter().map(|s| s.to_string()).collect(),
                code: Vec::new(),
                temporary: 0,
                preheader: 0
            });
            continue;
        }
        if words[0] == "end" {
            continue;
        }
        let function = program.functions.last_mut().unwrap();
        if words.len() == 1 && words[0].ends_with(':') {
            function.code.push(Line::Label(words[0][..words[0].len() - 1].into()));
            continue;
        }
        let mut instruction = Instruction::new("copy");
        match words[0] {
            "goto" => {
                instruction.kind = "goto";
                instruction.target = words[1].into();
            },
            "if" => {
                instruction.kind = "if";
                instruction.a = Some(Operand::parse(words[1]));
                instruction.operation = words[2].into();
                instruction.b = Some(Operand::parse(words[3]));
                instruction.target = words[5].into();
            },
            "param" | "return" | "read" | "print" => {
                instruction.kind = match words[0] {
                    "param" => "param",
                    "return" => "return",
                    "read" => "read",
                    _ => "print"
                };
                if words.len() > 1 {
                    if instruction.kind == "read" {
                        instruction.destination = Some(words[1].into());
                    } else {
                        instruction.a = Some(Operand::parse(words[1]));
                    }
                }
            },
            _ => {
                if words[0].contains('[') {
                    instruction.kind = "store";
                    let (array, index) = indexed(words[0]);
                    instruction.array = array;
                    instruction.a = Some(index);
                    instruction.b = Some(Operand::parse(words[2]));
                }
                else {
                    let start = if words[0] == "call" {
                        0
                    } else {
                        instruction.destination = Some(words[0].into());
                        2
                    };
                    if words[start] == "call" {
                        instruction.kind = "call";
                        instruction.function = words[start + 1].into();
                        instruction.count = words[start + 2].parse().unwrap();
                    }
                    else if words.len() == 5 {
                        instruction.kind = "bin";
                        instruction.a = Some(Operand::parse(words[2]));
                        instruction.operation = words[3].into();
                        instruction.b = Some(Operand::parse(words[4]));
                    }
                    else if words[2].contains('[') {
                        instruction.kind = "load";
                        let (array, index) = indexed(words[2]);
                        instruction.array = array;
                        instruction.a = Some(index);
                    }
                    else {
                        instruction.a = Some(Operand::parse(words[2]));
                    }
                }
            }
        }
        function.code.push(Line::Instruction(instruction));
    }
    program
}
pub fn operation(op: &str, a: i64, b: i64) -> i64 {
    match op {
        "+" => a + b,
        "-" => a - b,
        "*" => a * b,
        "/" => a / b,
        "%" => a % b,
        "<" => if a < b {
            1
        } else {
            0
        },
        "<=" => if a <= b {
            1
        } else {
            0
        },
        ">" => if a > b {
            1
        } else {
            0
        },
        ">=" => if a >= b {
            1
        } else {
            0
        },
        "==" => if a == b {
            1
        } else {
            0
        },
        "!=" => if a != b {
            1
        } else {
            0
        },
        _ => unreachable!()
    }
}
pub fn labels(function: &Function) -> BTreeMap<String, usize> {
    let mut labels = BTreeMap::new();
    let mut index = 0;
    for line in &function.code {
        match line {
            Line::Label(label) => {
                labels.insert(label.clone(), index);
            },
            Line::Instruction(_) => index += 1
        }
    }
    labels
}
